"use client"

import * as React from "react"
import { AsciiSweep, type AsciiSweepCharset } from "@/components/ui/ascii-sweep"
import { useHoverCapable } from "@/lib/hooks/use-hover-capable"
import { cn } from "@/lib/utils"

export interface AsciiImageRevealProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** Primary image displayed by default. */
  src: string
  /** Image alt text. */
  alt?: string
  /** Hidden image revealed on hover or tap. */
  revealSrc: string
  /** Hidden image alt text. */
  revealAlt?: string
  /** Optional caption or title shown on the card. */
  title?: string
  /** Optional subtitle or metadata tag. */
  subtitle?: string
  /** Optional badge text displayed in the top corner. */
  badge?: string
  /** Optional badge icon or element. */
  badgeIcon?: React.ReactNode
  /** Color of the sweeping characters, as any CSS color. */
  color?: string
  /** Sweep duration in seconds. */
  duration?: number
  /** Sweep direction in degrees. 0 sweeps left to right, 90 bottom to top. */
  angle?: number
  /** Width of the ASCII band as a fraction of travel (0 to 1). */
  band?: number
  /** Soft phosphor glow intensity around the characters. */
  glow?: number
  /** How ragged the sweep edge is across image rows. */
  turbulence?: number
  /** Built-in character ramp: real ASCII glyphs, shade blocks, or binary digits. */
  charset?: AsciiSweepCharset
  /** Controlled revealed state. */
  isRevealed?: boolean
  /** Initial revealed state when uncontrolled. */
  defaultRevealed?: boolean
  /** Callback fired when revealed state changes. */
  onRevealedChange?: (revealed: boolean) => void
  /** Additional classes applied to the image elements. */
  imageClassName?: string
}

export function AsciiImageReveal({
  src,
  alt = "Primary image",
  revealSrc,
  revealAlt = "Revealed image",
  title,
  subtitle,
  badge,
  badgeIcon,
  color = "#4ade80",
  duration = 1.4,
  angle = 0,
  band = 0.28,
  glow = 2,
  turbulence = 0.45,
  charset = "ascii",
  isRevealed,
  defaultRevealed = false,
  onRevealedChange,
  imageClassName,
  className,
  ...props
}: AsciiImageRevealProps) {
  const [internalRevealed, setInternalRevealed] = React.useState(defaultRevealed)
  const canHover = useHoverCapable()

  const isControlled = isRevealed !== undefined
  const active = isControlled ? isRevealed : internalRevealed

  const setRevealed = React.useCallback(
    (next: boolean) => {
      if (!isControlled) {
        setInternalRevealed(next)
      }
      onRevealedChange?.(next)
    },
    [isControlled, onRevealedChange]
  )

  const handlePointerEnter = () => {
    if (canHover) {
      setRevealed(true)
    }
  }

  const handlePointerLeave = () => {
    if (canHover) {
      setRevealed(false)
    }
  }

  const handleClick = () => {
    if (!canHover) {
      setRevealed(!active)
    }
  }

  const handleFocus = () => {
    setRevealed(true)
  }

  const handleBlur = () => {
    setRevealed(false)
  }

  return (
    <div
      data-slot="ascii-image-reveal"
      tabIndex={0}
      role="region"
      aria-label={title ?? alt}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onClick={handleClick}
      onFocus={handleFocus}
      onBlur={handleBlur}
      className={cn(
        "group relative overflow-hidden rounded-2xl border border-zinc-200 bg-zinc-950 shadow-xl dark:border-zinc-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 cursor-pointer select-none",
        className
      )}
      {...props}
    >
      <AsciiSweep
        index={active ? 1 : 0}
        duration={duration}
        angle={angle}
        band={band}
        color={color}
        glow={glow}
        turbulence={turbulence}
        charset={charset}
        className="h-full w-full"
        alternate={
          <div className="relative h-full w-full overflow-hidden bg-zinc-950">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={revealSrc}
              alt={revealAlt}
              className={cn(
                "h-full w-full object-cover transition-transform duration-500 group-hover:scale-105",
                imageClassName
              )}
            />
          </div>
        }
      >
        <div className="relative h-full w-full overflow-hidden bg-zinc-950">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={src}
            alt={alt}
            className={cn(
              "h-full w-full object-cover transition-transform duration-500 group-hover:scale-105",
              imageClassName
            )}
          />
        </div>
      </AsciiSweep>

      {badge ? (
        <div className="pointer-events-none absolute left-3 top-3 z-10 inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-black/60 px-2.5 py-1 text-[11px] font-medium text-white backdrop-blur-md shadow-xs">
          {badgeIcon}
          <span>{badge}</span>
        </div>
      ) : null}

      {title || subtitle ? (
        <div className="pointer-events-none absolute inset-x-0 bottom-0 z-10 bg-gradient-to-t from-black/90 via-black/40 to-transparent p-4 text-white">
          {title ? (
            <h3 className="text-sm font-semibold tracking-tight text-white leading-tight">
              {title}
            </h3>
          ) : null}
          {subtitle ? (
            <p className="text-[11px] text-zinc-300 font-medium mt-0.5">
              {subtitle}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}
